def transform(grid):
    """Decode a tiled lattice into cells whose four corners share a marker."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill = counts.most_common(1)[0][0]
    separator = counts.most_common(2)[1][0]

    # Separator-heavy full grid lines; markers replace separator at nodes.
    rows = [r for r in range(h)
            if sum(v == separator for v in grid[r]) > w / 2]
    cols = [c for c in range(w)
            if sum(grid[r][c] == separator for r in range(h)) > h / 2]

    out = []
    for r0, r1 in zip(rows, rows[1:]):
        row = []
        for c0, c1 in zip(cols, cols[1:]):
            color = grid[r0][c0]
            corners = (color, grid[r0][c1], grid[r1][c0], grid[r1][c1])
            if color != separator and color != fill and all(x == color for x in corners):
                row.append(color)
            else:
                row.append(fill)
        out.append(row)

    # Remove unused all-fill margins around the encoded picture.
    while out and all(x == fill for x in out[0]):
        out.pop(0)
    while out and all(x == fill for x in out[-1]):
        out.pop()
    if out:
        while all(row[0] == fill for row in out):
            for row in out:
                row.pop(0)
        while out and all(row[-1] == fill for row in out):
            for row in out:
                row.pop()
    return out
